import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第五百二十六章 「有」是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/526第五百二十六章 「有」是什么.md","filePath":"meditation/巴利文大藏经/526第五百二十六章 「有」是什么.md"}'),r={name:"meditation/巴利文大藏经/526第五百二十六章 「有」是什么.md"};function _(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第五百二十六章-「有」是什么" tabindex="-1">第五百二十六章 「有」是什么？ <a class="header-anchor" href="#第五百二十六章-「有」是什么" aria-label="Permalink to &quot;第五百二十六章 「有」是什么？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部38相应13经/有的询问经(阎浮车相应/处篇/弟子记说)</p><p>有个时候，舍利弗尊者住在摩揭陀国的那拉迦村中，有一天，外教修行人阎浮车来到舍利弗尊者的住处，他与舍利弗尊者互相问候后，就在一旁坐下，阎浮车对舍利弗尊者说：“舍利弗道友，什么被称为「有」呢？什么是「有」呢？”</p><p>舍利弗尊者说：“阎浮车道友，所谓「有」就是存在，有因缘果报，也就是有做善事得善报，做恶事得恶报，有生与死的因果。有三种「有」：有欲望、欲望世界的存在，有欲望、欲望世界的因果报应，有欲望、欲望世界生死的因果；有物质事物、物质世界的存在，有物质事物、物质世界的因果报应，有物质事物、物质世界生死的因果；有念想、见解、精神世界的存在，有念想、见解、精神世界的因果报应，有念想、见解、精神世界生死的因果。这些就是三种「有」。”</p><p>阎浮车说：“舍利弗道友，如何完全明白和理解三种「有」呢？如何亲身体验到三种「有」呢？如何验证三种「有」的存在呢？”</p><p>舍利弗尊者说：“阎浮车道友，修习八正道（八正道解释，见第十八章），就能完全明白和理解三种「有」，就能亲身体验到三种「有」，就能验证三种「有」的存在，也即是修习正见、正志、正语、正业、正命、正方便、正念、正定，这八种正道就能完全明白和理解三种「有」，就能亲身体验到三种「有」，就能验证三种「有」的存在。”</p><p>阎浮车说：“舍利弗道友，我明白了，修习八正道就能完全明白和理解三种「有」，就能亲身体验到三种「有」，就能验证三种「有」的存在。八正道确实能够让人走上善道，八正道确实是善法，如果用八正道来熄灭、除灭恶行、恶语、恶念那确实已经足够了，如果用八正道来管束自己，让自己的行为、言语、念想不做恶事，让自己不放逸已经完全足够了，舍利弗道友，我已经知道了完全明白和理解三种「有」，亲身体验到三种「有」，验证三种「有」存在的修行方法，非常感谢您。”</p><p>舍利弗尊者说法后，阎浮车虔诚恭敬的顶礼舍利弗尊者，随喜赞叹舍利弗尊者说法的无量功德，并按着舍利弗尊者所说的法去修行。</p>',9)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
